{
  "root": "main_stack",
  "state": {
    "itinerary": [
      {
        "id": "day1",
        "day": "Day 1",
        "title": "Ancient Grandeur & Roman Forum",
        "image": "../assets/r_000646_01_1_Colosseum_in_Rome__Italy_-_April_2007.jpg",
        "imageAlt": "Colosseum in Rome",
        "icon": "../assets/r_000646_01_2_building.svg",
        "morning": "Immerse yourself in ancient history with a visit to the Colosseum, followed by the sprawling ruins of the Roman Forum and Palatine Hill. Tip: Pre-book a combined ticket online to save time.",
        "afternoon": "Stroll along Via dei Fori Imperiali, leading to Piazza Venezia and the imposing Altare della Patria (Victor Emmanuel II Monument). Ascend Capitoline Hill for panoramic views of the Forum.",
        "food": "Enjoy an authentic Roman lunch at a traditional trattoria near the Colosseum, trying classic pasta dishes like Cacio e Pepe or Carbonara. For dinner, explore the Monti neighborhood for cozy eateries."
      },
      {
        "id": "day2",
        "day": "Day 2",
        "title": "Vatican City & Baroque Masterpieces",
        "image": null,
        "imageAlt": null,
        "icon": "../assets/r_000646_01_4_geo-alt.svg",
        "morning": "Begin your day in Vatican City. Explore the Vatican Museums, including the breathtaking Sistine Chapel, then marvel at the grandeur of St. Peter's Basilica. Tip: Book tickets online in advance and adhere to the dress code (covered shoulders and knees).",
        "afternoon": "Cross Ponte Sant'Angelo to reach Castel Sant'Angelo, offering historical insights and beautiful city views. Later, wander through Piazza Navona with its stunning fountains and visit the ancient Pantheon.",
        "food": "Grab a quick and delicious 'pizza al taglio' (pizza by the slice) for lunch. For dinner, find a charming restaurant in the area around the Pantheon, perhaps trying supplí (fried rice balls)."
      },
      {
        "id": "day3",
        "day": "Day 3",
        "title": "Iconic Fountains, Spanish Steps & Trastevere Charm",
        "image": null,
        "imageAlt": null,
        "icon": "../assets/r_000639_01_2_water.svg",
        "morning": "Start with a visit to the magnificent Trevi Fountain (don't forget to toss a coin!). Continue to the elegant Spanish Steps and explore the high-end shops along Via del Corso.",
        "afternoon": "Head to the charming neighborhood of Trastevere. Get lost in its narrow, cobblestone streets, browse artisan shops, and soak in the bohemian atmosphere. Consider visiting Santa Maria in Trastevere church.",
        "food": "Indulge in some authentic Italian gelato. For your farewell dinner, choose a lively trattoria in Trastevere, known for its traditional Roman cuisine and vibrant evening ambiance."
      }
    ],
    "travelTips": [
      {
        "id": "tip1",
        "tip": "Accommodation",
        "details": "This itinerary assumes your accommodation is separate from the daily €100 budget. Look for hostels or budget hotels, especially in areas like Termini, Monti, or San Lorenzo."
      },
      {
        "id": "tip2",
        "tip": "Transportation",
        "details": "Rome's public transport (Metro, buses, trams) is efficient. A 72-hour pass (BIT) or a multi-day pass can be cost-effective for unlimited travel. Most major sites are walkable."
      },
      {
        "id": "tip3",
        "tip": "Budgeting",
        "details": "Food: Aim for €15-20 for lunch (pizza al taglio, street food, casual trattoria) and €25-40 for dinner. Gelato and coffee are generally affordable. Activities: Colosseum/Forum/Palatine combined ticket is around €18. Vatican Museums are around €20. Many churches and piazzas are free."
      },
      {
        "id": "tip4",
        "tip": "Safety",
        "details": "Rome is generally safe, but be aware of pickpockets, especially in crowded tourist areas and on public transport. Keep valuables secure."
      },
      {
        "id": "tip5",
        "tip": "Language",
        "details": "While many Romans speak English, learning a few basic Italian phrases like 'Buongiorno' (Good morning), 'Grazie' (Thank you), and 'Scusi' (Excuse me) will be appreciated."
      },
      {
        "id": "tip6",
        "tip": "Comfortable Shoes",
        "details": "You'll be doing a lot of walking on cobblestone streets, so comfortable footwear is a must."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "daily_exploration_heading",
        "itinerary_table",
        "travel_tips_heading",
        "travel_tips_table",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Rome Solo Adventure: A 3-Day Itinerary",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Embark on a captivating solo journey through Rome, exploring its ancient wonders, artistic masterpieces, and vibrant culinary scene at a moderate pace. This itinerary balances iconic sights with opportunities to savor local life, keeping your daily activity and food budget around €100."
      },
      "children": []
    },
    "daily_exploration_heading": {
      "type": "Text",
      "props": {
